class Solution { int[] parent,size;private int find(int value){return value==parent[value]?value:(parent[value]=find(parent[value]));}private void union(int a,int b){a=find(a);b=find(b);if(a==b)return;if(size[a]<size[b]){int t=a;a=b;b=t;}parent[b]=a;size[a]+=size[b];}public int[] groupStrings(String[] words){int n=words.length;parent=new int[n];size=new int[n];Map<Integer,Integer> masks=new HashMap<>();int[] values=new int[n];for(int i=0;i<n;i++){parent[i]=i;size[i]=1;int mask=0;for(char ch:words[i].toCharArray())mask|=1<<(ch-'a');values[i]=mask;if(masks.containsKey(mask))union(i,masks.get(mask));else masks.put(mask,i);}Map<Integer,Integer> removedOwner=new HashMap<>();for(int i=0;i<n;i++)for(int bits=values[i];bits!=0;bits&=bits-1){int removed=values[i]^(bits&-bits);if(masks.containsKey(removed))union(i,masks.get(removed));if(removedOwner.containsKey(removed))union(i,removedOwner.get(removed));else removedOwner.put(removed,i);}Set<Integer> roots=new HashSet<>();int maximum=0;for(int i=0;i<n;i++){int root=find(i);roots.add(root);maximum=Math.max(maximum,size[root]);}return new int[]{roots.size(),maximum};} }
